-- ==========================================================================
-- 20261020000015_embedding_fks
-- ==========================================================================

-- Direct foreign keys so PostgREST can embed related rows.
--
-- tutor_competencies already has a COMPOSITE foreign key to
-- subject_offerings (subject_code, grade_code), which is the real constraint:
-- a tutor may only be competent in something the centre actually offers at
-- that grade. But PostgREST resolves embeds from single-column foreign keys,
-- so `select subjects(name)` from tutor_competencies fails at runtime without
-- these - it is not merely a typing inconvenience.
--
-- These are redundant in the sense that the composite key already guarantees
-- the referenced rows exist. They are kept because the alternative - joining
-- manually in every query, or embedding through subject_offerings - makes the
-- common read path worse for no modelling gain. No data is duplicated; only
-- the referential statement is.

alter table public.tutor_competencies
  add constraint tutor_competencies_subject_code_fkey
    foreign key (subject_code) references public.subjects (code),
  add constraint tutor_competencies_grade_code_fkey
    foreign key (grade_code) references public.grades (code);

comment on constraint tutor_competencies_subject_code_fkey on public.tutor_competencies is
  'For PostgREST embedding. The composite FK to subject_offerings is the real rule.';

insert into public.schema_migrations (version) values ('20261020000015_embedding_fks');

-- ==========================================================================
-- 20261020000016_enrolment_rpcs
-- ==========================================================================

-- Transactional operations for enrolment and timetabling.
--
-- These are RPCs rather than a sequence of client inserts because each one
-- must be all-or-nothing. A learner created without consents, or an enrolment
-- activated without its registration invoice, is worse than a failed attempt -
-- the first is a POPIA problem, the second a billing one.

-- Submit an enrolment -------------------------------------------------------
-- Runs as the signed-in guardian. Creates the learner, the guardian link, the
-- safeguarding records, the consents and a PENDING enrolment in one go.
create or replace function public.submit_enrolment(
  p_learner        jsonb,
  p_package_code   text,
  p_subjects       jsonb,
  p_emergency      jsonb,
  p_collectors     jsonb,
  p_consents       jsonb,
  p_policy_version text,
  p_preferred_tutor uuid default null
)
returns uuid
language plpgsql security definer set search_path = ''
as $fn$
declare
  v_guardian uuid := (select auth.uid());
  v_learner  uuid;
  v_enrolment uuid;
  v_item jsonb;
  v_required integer;
  v_granted integer;
begin
  if v_guardian is null then
    raise exception 'Not signed in' using errcode = 'P0001';
  end if;
  if not exists (select 1 from public.guardians where profile_id = v_guardian) then
    raise exception 'Only a parent or guardian can enrol a learner' using errcode = 'P0001';
  end if;

  -- Every required consent must be present and granted. POPIA s35 is checked
  -- here as well as by the activation trigger, so an incomplete submission
  -- never creates a learner record at all.
  select count(*) into v_required from public.consent_types where is_required;
  select count(*) into v_granted
  from jsonb_array_elements(p_consents) c
  join public.consent_types ct on ct.code = c ->> 'consent_type_code'
  where ct.is_required and (c ->> 'granted')::boolean;

  if v_granted < v_required then
    raise exception 'All required consents must be given before a learner can be registered'
      using errcode = 'check_violation';
  end if;

  if jsonb_array_length(p_emergency) < 1 then
    raise exception 'At least one emergency contact is required'
      using errcode = 'check_violation';
  end if;

  insert into public.learners (full_name, date_of_birth, grade_code, school_name, home_language_code, status)
  values (
    p_learner ->> 'full_name',
    (p_learner ->> 'date_of_birth')::date,
    p_learner ->> 'grade_code',
    coalesce(p_learner ->> 'school_name', ''),
    nullif(p_learner ->> 'home_language_code', '')
  , 'prospective')
  returning id into v_learner;

  insert into public.learner_guardians (learner_id, guardian_id, relationship, is_primary, is_billing_contact)
  values (v_learner, v_guardian, coalesce(p_learner ->> 'relationship', 'guardian'), true, true);

  for v_item in select * from jsonb_array_elements(p_emergency) loop
    insert into public.learner_emergency_contacts (learner_id, full_name, relationship, phone, priority)
    values (v_learner, v_item ->> 'full_name', v_item ->> 'relationship', v_item ->> 'phone',
            coalesce((v_item ->> 'priority')::smallint, 1));
  end loop;

  for v_item in select * from jsonb_array_elements(coalesce(p_collectors, '[]'::jsonb)) loop
    insert into public.authorised_collectors (learner_id, full_name, relationship, phone, id_number_last4)
    values (v_learner, v_item ->> 'full_name', v_item ->> 'relationship', v_item ->> 'phone',
            nullif(v_item ->> 'id_number_last4', ''));
  end loop;

  for v_item in select * from jsonb_array_elements(p_consents) loop
    insert into public.consents (consent_type_code, guardian_id, learner_id, granted, policy_version)
    values (v_item ->> 'consent_type_code', v_guardian, v_learner,
            (v_item ->> 'granted')::boolean, p_policy_version);
  end loop;

  insert into public.enrolments (learner_id, package_code, status, preferred_tutor_id, source)
  values (v_learner, p_package_code, 'pending', p_preferred_tutor, 'website')
  returning id into v_enrolment;

  for v_item in select * from jsonb_array_elements(coalesce(p_subjects, '[]'::jsonb)) loop
    insert into public.enrolment_subjects (enrolment_id, subject_code, preferred_language_code)
    values (v_enrolment, v_item ->> 'subject_code', nullif(v_item ->> 'preferred_language_code', ''));
  end loop;

  return v_enrolment;
end;
$fn$;

revoke execute on function public.submit_enrolment(jsonb, text, jsonb, jsonb, jsonb, jsonb, text, uuid) from public, anon;
grant execute on function public.submit_enrolment(jsonb, text, jsonb, jsonb, jsonb, jsonb, text, uuid) to authenticated;

-- Activate an enrolment -----------------------------------------------------
-- Admin approval. Sets the enrolment live, opens a billing account if the
-- family does not have one, and raises the once-off registration invoice
-- immediately (SPEC rule 6b). Tuition joins the normal 15th cycle.
create or replace function public.activate_enrolment(
  p_enrolment_id      uuid,
  p_assigned_tutor_id uuid,
  p_start_date        date default current_date,
  p_first_month_cents integer default null,
  p_reason            text default null
)
returns uuid
language plpgsql security definer set search_path = ''
as $fn$
declare
  v_admin     uuid := (select auth.uid());
  v_enrolment public.enrolments;
  v_guardian  uuid;
  v_account   uuid;
  v_invoice   uuid;
  v_fee       integer;
begin
  if not (select private.is_admin()) then
    raise exception 'Administrators only' using errcode = 'P0001';
  end if;

  select * into v_enrolment from public.enrolments where id = p_enrolment_id for update;
  if not found then raise exception 'Enrolment not found' using errcode = 'P0001'; end if;
  if v_enrolment.status <> 'pending' then
    raise exception 'Only a pending enrolment can be activated' using errcode = 'P0001';
  end if;

  select guardian_id into v_guardian
  from public.learner_guardians
  where learner_id = v_enrolment.learner_id and is_billing_contact;
  if v_guardian is null then
    raise exception 'Learner has no billing contact' using errcode = 'check_violation';
  end if;

  -- The consent and billing-contact triggers also guard this update.
  update public.enrolments
     set status                   = 'active',
         assigned_tutor_id        = p_assigned_tutor_id,
         start_date               = p_start_date,
         activated_at             = now(),
         first_month_amount_cents = p_first_month_cents,
         first_month_set_by       = case when p_first_month_cents is not null then v_admin end,
         first_month_reason       = p_reason
   where id = p_enrolment_id;

  update public.learners set status = 'active', joined_on = p_start_date
   where id = v_enrolment.learner_id and status = 'prospective';

  select id into v_account from public.billing_accounts where guardian_id = v_guardian;
  if v_account is null then
    insert into public.billing_accounts (guardian_id) values (v_guardian) returning id into v_account;
  end if;

  -- Registration is charged once per learner, not once per enrolment.
  if not exists (
    select 1 from public.invoice_lines l
    where l.learner_id = v_enrolment.learner_id and l.line_type = 'registration'
  ) then
    v_fee := public.package_price_on('registration', p_start_date);
    insert into public.invoices (billing_account_id, invoice_number, issued_on, due_on, status, notes)
    values (v_account, private.next_invoice_number(p_start_date), p_start_date, p_start_date, 'issued',
            'Registration fee')
    returning id into v_invoice;

    insert into public.invoice_lines (invoice_id, line_type, description, package_code, learner_id, unit_amount_cents)
    values (v_invoice, 'registration', 'Registration fee', 'registration', v_enrolment.learner_id, coalesce(v_fee, 0));
  end if;

  return v_invoice;
end;
$fn$;

revoke execute on function public.activate_enrolment(uuid, uuid, date, integer, text) from public, anon;
grant execute on function public.activate_enrolment(uuid, uuid, date, integer, text) to authenticated;

-- Generate the term's sessions ---------------------------------------------
-- Materialises one class_session per scheduled day inside the class's term.
-- Idempotent: re-running after adding a schedule fills only the gaps.
create or replace function public.generate_class_sessions(p_class_group_id uuid)
returns integer
language plpgsql security definer set search_path = ''
as $fn$
declare v_count integer;
begin
  if not (select private.is_admin()) then
    raise exception 'Administrators only' using errcode = 'P0001';
  end if;

  with created as (
    insert into public.class_sessions (class_group_id, schedule_id, session_date, starts_at, ends_at)
    select cg.id, s.id, d::date,
           -- The date and time are wall-clock at the centre; `at time zone`
           -- resolves them to the correct instant, including over DST.
           (d::date + s.starts_at_time) at time zone 'Africa/Johannesburg',
           (d::date + s.ends_at_time)   at time zone 'Africa/Johannesburg'
    from public.class_groups cg
    join public.terms t            on t.id = cg.term_id
    join public.class_schedules s  on s.class_group_id = cg.id
    cross join lateral generate_series(t.starts_on::timestamp, t.ends_on::timestamp, interval '1 day') d
    where cg.id = p_class_group_id
      and extract(isodow from d) = s.day_of_week
    on conflict (class_group_id, session_date, starts_at) do nothing
    returning 1
  )
  select count(*) into v_count from created;

  return v_count;
end;
$fn$;

revoke execute on function public.generate_class_sessions(uuid) from public, anon;
grant execute on function public.generate_class_sessions(uuid) to authenticated;

insert into public.schema_migrations (version) values ('20261020000016_enrolment_rpcs');

-- ==========================================================================
-- 20261020000017_write_grants
-- ==========================================================================

-- Table grants for the authenticated role.
--
-- RLS policies decide WHO may write a row; a GRANT decides whether the role
-- may attempt the statement at all. Both are needed. Phase 1 and 2 granted
-- writes only on the tables parents and tutors touch, which left every
-- admin-managed table ungranted - the policies existed and could never fire.
--
-- The model from here is the usual Supabase one: grant the statement to
-- `authenticated`, and let RLS be the control. `anon` stays locked down.

grant insert, update on all tables in schema public to authenticated;

-- `all tables` includes the migration ledger, which is infrastructure.
revoke all on public.schema_migrations from anon, authenticated;

-- DELETE is granted deliberately, not broadly. These are rows that are edited
-- as sets - a class's weekly slots, the subjects on an enrolment, the lines on
-- a draft invoice - where removing one is ordinary editing.
grant delete on
  public.class_schedules, public.class_group_grades, public.class_sessions,
  public.class_enrolments, public.tutor_competencies, public.tutor_competency_media,
  public.tutor_spoken_languages, public.tutor_qualifications, public.tutor_references,
  public.tutor_documents, public.tutor_pay_rates, public.enrolment_subjects,
  public.invoice_lines, public.payment_allocations, public.credit_note_allocations,
  public.resource_audiences, public.assessment_scores, public.learning_plan_goals,
  public.progress_report_subjects, public.programme_sessions, public.programme_enrolments,
  public.notification_recipients, public.thread_participants, public.expenses,
  public.subject_offerings, public.learner_emergency_contacts, public.authorised_collectors
to authenticated;

-- Not deletable by anyone through the API, on purpose:
--   learners, enrolments, invoices, payments, consents, attendance_records,
--   assessments, progress_reports, data_retention_log
-- These carry POPIA retention, financial history or an audit trail. Removing
-- them is the retention job's business, with administrator confirmation, not
-- a stray DELETE from a screen.

-- Append-only by design. These are records of what happened, not state:
--   messages                - what was actually said to a parent
--   report_acknowledgements - that a parent saw a particular report
--   thread_participants     - membership changes by adding or removing a row
-- Editing one after the fact would rewrite history, so UPDATE is withheld and
-- the absence of an UPDATE policy is deliberate, not an oversight.
revoke update on public.messages, public.report_acknowledgements,
                 public.thread_participants
from authenticated;

-- anon submits an enquiry and reads the public site. Nothing else.
revoke insert, update, delete on all tables in schema public from anon;
grant insert on public.contact_enquiries to anon;

insert into public.schema_migrations (version) values ('20261020000017_write_grants');

-- ==========================================================================
-- 20261020000018_tutor_admin
-- ==========================================================================

-- Administrator tutor management.
--
-- Tutors are created by the centre, never by self-application (BR-23). The
-- person signs up as an ordinary account first; an administrator then grants
-- the tutor role and creates the staff record.
--
-- This needs a lookup in auth.users, which PostgREST does not expose, so it
-- is a SECURITY DEFINER function rather than a client query. The alternative -
-- copying email onto profiles - would duplicate a fact auth.users already
-- owns, and the two would drift the first time someone changes their address.

create or replace function public.create_tutor(
  p_email           text,
  p_slug            text,
  p_employment_type text,
  p_headline        text default ''
)
returns uuid
language plpgsql security definer set search_path = ''
as $fn$
declare
  v_user  uuid;
  v_tutor uuid;
begin
  if not (select private.is_admin()) then
    raise exception 'Administrators only' using errcode = 'P0001';
  end if;

  select id into v_user from auth.users where lower(email) = lower(trim(p_email));
  if v_user is null then
    raise exception 'No account exists for %. Ask them to sign up first, then add them here.', p_email
      using errcode = 'P0001';
  end if;

  if exists (select 1 from public.tutors where profile_id = v_user) then
    raise exception 'That person is already a tutor' using errcode = 'unique_violation';
  end if;

  insert into public.user_roles (user_id, role) values (v_user, 'tutor')
  on conflict (user_id, role) do nothing;

  insert into public.tutors (profile_id, slug, employment_type, headline)
  values (v_user, p_slug, p_employment_type, coalesce(p_headline, ''))
  returning id into v_tutor;

  return v_tutor;
end;
$fn$;

revoke execute on function public.create_tutor(text, text, text, text) from public, anon;
grant execute on function public.create_tutor(text, text, text, text) to authenticated;

-- Record one teaching competency and the languages it is taught in.
-- Grouped into a function because a competency without a medium is useless:
-- no class can ever be assigned to it, so the two belong in one step.
create or replace function public.set_tutor_competency(
  p_tutor_id   uuid,
  p_subject    text,
  p_grade      text,
  p_languages  text[]
)
returns uuid
language plpgsql security definer set search_path = ''
as $fn$
declare v_id uuid; v_lang text;
begin
  if not (select private.is_admin()) then
    raise exception 'Administrators only' using errcode = 'P0001';
  end if;
  if coalesce(array_length(p_languages, 1), 0) = 0 then
    raise exception 'Choose at least one language of instruction' using errcode = 'check_violation';
  end if;

  insert into public.tutor_competencies (tutor_id, subject_code, grade_code)
  values (p_tutor_id, p_subject, p_grade)
  on conflict (tutor_id, subject_code, grade_code) do update set tutor_id = excluded.tutor_id
  returning id into v_id;

  delete from public.tutor_competency_media where competency_id = v_id;
  foreach v_lang in array p_languages loop
    insert into public.tutor_competency_media (competency_id, language_code) values (v_id, v_lang);
  end loop;

  return v_id;
end;
$fn$;

revoke execute on function public.set_tutor_competency(uuid, text, text, text[]) from public, anon;
grant execute on function public.set_tutor_competency(uuid, text, text, text[]) to authenticated;

-- Set a pay rate, closing the previous one so the periods never overlap.
create or replace function public.set_tutor_pay_rate(
  p_tutor_id       uuid,
  p_pay_basis      text,
  p_amount_cents   integer,
  p_effective_from date default current_date
)
returns uuid
language plpgsql security definer set search_path = ''
as $fn$
declare v_id uuid;
begin
  if not (select private.is_admin()) then
    raise exception 'Administrators only' using errcode = 'P0001';
  end if;

  -- The exclusion constraint forbids overlap, so close the open rate first
  -- rather than leaving the caller to discover the clash.
  update public.tutor_pay_rates
     set effective_to = p_effective_from
   where tutor_id = p_tutor_id
     and effective_to is null
     and effective_from < p_effective_from;

  insert into public.tutor_pay_rates (tutor_id, pay_basis, amount_cents, effective_from)
  values (p_tutor_id, p_pay_basis, p_amount_cents, p_effective_from)
  returning id into v_id;

  return v_id;
end;
$fn$;

revoke execute on function public.set_tutor_pay_rate(uuid, text, integer, date) from public, anon;
grant execute on function public.set_tutor_pay_rate(uuid, text, integer, date) to authenticated;

insert into public.schema_migrations (version) values ('20261020000018_tutor_admin');

-- ==========================================================================
-- 20261020000019_assessment_rpcs
-- ==========================================================================

-- Assessment, learning plan and progress report operations.
-- BP section 12 and the value chain in section 10.

-- Record an assessment with its per-domain scores in one transaction.
-- An assessment with no scores is not a partial record, it is a useless one.
create or replace function public.record_assessment(
  p_learner_id uuid,
  p_type       text,
  p_grade_code text,
  p_assessed_on date,
  p_scores     jsonb,
  p_subject    text default null,
  p_term_id    uuid default null,
  p_notes      text default ''
)
returns uuid
language plpgsql security definer set search_path = ''
as $fn$
declare
  v_tutor uuid := (select private.my_tutor_id());
  v_id    uuid;
  v_item  jsonb;
  v_level smallint;
begin
  if v_tutor is null and not (select private.is_admin()) then
    raise exception 'Only the teaching tutor or an administrator may record an assessment'
      using errcode = 'P0001';
  end if;
  if v_tutor is not null and not (select private.tutor_teaches(p_learner_id))
     and not (select private.is_admin()) then
    raise exception 'You do not teach this learner' using errcode = 'P0001';
  end if;
  if jsonb_array_length(coalesce(p_scores, '[]'::jsonb)) = 0 then
    raise exception 'Record a score for at least one domain' using errcode = 'check_violation';
  end if;

  insert into public.assessments
    (learner_id, assessment_type_code, subject_code, grade_code, term_id, administered_by, assessed_on, notes)
  values (p_learner_id, p_type, p_subject, p_grade_code, p_term_id, v_tutor, p_assessed_on, coalesce(p_notes, ''))
  returning id into v_id;

  for v_item in select * from jsonb_array_elements(p_scores) loop
    -- The achievement level follows from the percentage, so derive it rather
    -- than asking the tutor to pick a band that might disagree with the mark.
    select code into v_level
    from public.achievement_levels
    where round((v_item ->> 'raw_score')::numeric * 100
                / nullif((v_item ->> 'max_score')::numeric, 0)) between min_percent and max_percent;

    insert into public.assessment_scores
      (assessment_id, domain_code, raw_score, max_score, achievement_level_code, comment)
    values (v_id, v_item ->> 'domain_code',
            (v_item ->> 'raw_score')::numeric,
            (v_item ->> 'max_score')::numeric,
            v_level,
            coalesce(v_item ->> 'comment', ''));
  end loop;

  return v_id;
end;
$fn$;

revoke execute on function public.record_assessment(uuid, text, text, date, jsonb, text, uuid, text) from public, anon;
grant execute on function public.record_assessment(uuid, text, text, date, jsonb, text, uuid, text) to authenticated;

-- Create an individual learning plan with its goals, superseding any current
-- one. A learner has at most one active plan (enforced by a unique index), so
-- the previous plan must be closed in the same transaction.
create or replace function public.create_learning_plan(
  p_learner_id    uuid,
  p_goals         jsonb,
  p_assessment_id uuid default null,
  p_term_id       uuid default null
)
returns uuid
language plpgsql security definer set search_path = ''
as $fn$
declare v_id uuid; v_item jsonb;
begin
  if not (select private.tutor_teaches(p_learner_id)) and not (select private.is_admin()) then
    raise exception 'You do not teach this learner' using errcode = 'P0001';
  end if;
  if jsonb_array_length(coalesce(p_goals, '[]'::jsonb)) = 0 then
    raise exception 'A learning plan needs at least one goal' using errcode = 'check_violation';
  end if;

  update public.learning_plans set status = 'superseded'
   where learner_id = p_learner_id and status = 'active';

  insert into public.learning_plans
    (learner_id, from_assessment_id, term_id, status, created_by, activated_at)
  values (p_learner_id, p_assessment_id, p_term_id, 'active', (select auth.uid()), now())
  returning id into v_id;

  for v_item in select * from jsonb_array_elements(p_goals) loop
    insert into public.learning_plan_goals
      (learning_plan_id, subject_code, goal, target_level_code, target_date)
    values (v_id, v_item ->> 'subject_code', v_item ->> 'goal',
            nullif(v_item ->> 'target_level_code', '')::smallint,
            nullif(v_item ->> 'target_date', '')::date);
  end loop;

  return v_id;
end;
$fn$;

revoke execute on function public.create_learning_plan(uuid, jsonb, uuid, uuid) from public, anon;
grant execute on function public.create_learning_plan(uuid, jsonb, uuid, uuid) to authenticated;

-- Write a termly report and its per-subject detail. Saves as a draft; the
-- parent sees nothing until it is published.
create or replace function public.save_progress_report(
  p_learner_id uuid,
  p_term_id    uuid,
  p_summary    text,
  p_subjects   jsonb,
  p_publish    boolean default false,
  p_attendance_note text default ''
)
returns uuid
language plpgsql security definer set search_path = ''
as $fn$
declare v_id uuid; v_item jsonb; v_tutor uuid := (select private.my_tutor_id());
begin
  if not (select private.tutor_teaches(p_learner_id)) and not (select private.is_admin()) then
    raise exception 'You do not teach this learner' using errcode = 'P0001';
  end if;
  if jsonb_array_length(coalesce(p_subjects, '[]'::jsonb)) = 0 then
    raise exception 'A report must cover at least one subject' using errcode = 'check_violation';
  end if;

  insert into public.progress_reports
    (learner_id, term_id, tutor_id, summary, attendance_note, created_by)
  values (p_learner_id, p_term_id, v_tutor, coalesce(p_summary, ''), coalesce(p_attendance_note, ''),
          (select auth.uid()))
  on conflict (learner_id, term_id) do update
    set summary = excluded.summary,
        attendance_note = excluded.attendance_note,
        tutor_id = coalesce(excluded.tutor_id, public.progress_reports.tutor_id)
  returning id into v_id;

  -- Rewritten wholesale: a report is edited as a document, not row by row.
  delete from public.progress_report_subjects where progress_report_id = v_id;
  for v_item in select * from jsonb_array_elements(p_subjects) loop
    insert into public.progress_report_subjects
      (progress_report_id, subject_code, achievement_level_code, strengths,
       areas_for_improvement, recommended_intervention)
    values (v_id, v_item ->> 'subject_code',
            nullif(v_item ->> 'achievement_level_code', '')::smallint,
            coalesce(v_item ->> 'strengths', ''),
            coalesce(v_item ->> 'areas_for_improvement', ''),
            coalesce(v_item ->> 'recommended_intervention', ''));
  end loop;

  -- Publishing is a one-way door: once a parent has been shown a report it
  -- is not silently unpublished.
  if p_publish then
    update public.progress_reports
       set published_at = coalesce(published_at, now())
     where id = v_id;
  end if;

  return v_id;
end;
$fn$;

revoke execute on function public.save_progress_report(uuid, uuid, text, jsonb, boolean, text) from public, anon;
grant execute on function public.save_progress_report(uuid, uuid, text, jsonb, boolean, text) to authenticated;

insert into public.schema_migrations (version) values ('20261020000019_assessment_rpcs');

-- ==========================================================================
-- 20261020000020_billing_run
-- ==========================================================================

-- The monthly invoice run, payment recording and late fees.
--
-- Two columns are added first. Without them, "has this enrolment already been
-- billed for November?" and "has this invoice already attracted a late fee?"
-- can only be answered by parsing descriptions, which is not an answer. With
-- them, both become unique indexes, so double-billing is structurally
-- impossible rather than merely avoided by careful code.

alter table public.invoice_lines
  add column period_month date,
  add column late_fee_for_invoice_id uuid references public.invoices (id) on delete set null;

comment on column public.invoice_lines.period_month is
  'The month a package line covers, as its first day. Null for once-off lines.';
comment on column public.invoice_lines.late_fee_for_invoice_id is
  'The overdue invoice this late fee relates to, so it is charged only once.';

-- One package line per enrolment per month, ever.
create unique index invoice_line_one_per_enrolment_month
  on public.invoice_lines (enrolment_id, period_month)
  where line_type = 'package' and enrolment_id is not null and period_month is not null;

-- One late fee per overdue invoice, ever.
create unique index invoice_line_one_late_fee_per_invoice
  on public.invoice_lines (late_fee_for_invoice_id)
  where line_type = 'late_fee' and late_fee_for_invoice_id is not null;

-- A package line must say which month it covers; a late fee must say which
-- invoice it punishes. Otherwise the indexes above have nothing to bite on.
alter table public.invoice_lines
  add constraint invoice_line_period_required
    check (line_type <> 'package' or period_month is not null),
  add constraint invoice_line_late_fee_target_required
    check (line_type <> 'late_fee' or late_fee_for_invoice_id is not null);

-- The monthly run --------------------------------------------------------
-- Bills every active enrolment for the target month, and catches up any
-- earlier month that was never billed - which is how a learner who joined
-- after the 15th gets their part-month and the month between (SPEC 9.3).
create or replace function public.run_monthly_invoices(p_period date default null)
returns table (invoice_id uuid, billing_account_id uuid, total_cents bigint)
language plpgsql security definer set search_path = ''
as $fn$
declare
  v_target   date;
  v_settings public.billing_settings;
  v_issued   date;
  v_due      date;
  v_enrol    record;
  v_month    date;
  v_amount   integer;
  v_account  uuid;
  v_invoice  uuid;
  v_touched  uuid[] := '{}';
begin
  if not (select private.is_admin()) then
    raise exception 'Administrators only' using errcode = 'P0001';
  end if;

  v_target := date_trunc('month', coalesce(p_period, (current_date + interval '1 month')))::date;

  select * into v_settings from public.billing_settings
   where effective_from <= v_target and (effective_to is null or v_target < effective_to);
  if v_settings is null then
    raise exception 'No billing settings are in effect for %', v_target using errcode = 'P0001';
  end if;

  -- Issued on the 15th of the preceding month, due on the 1st of the target.
  v_issued := (v_target - interval '1 month')::date + (v_settings.issue_day - 1);
  v_due    := v_target + (v_settings.due_day - 1);

  for v_enrol in
    select e.id, e.learner_id, e.package_code, e.start_date, e.first_month_amount_cents,
           lg.guardian_id
    from public.enrolments e
    join public.learner_guardians lg
      on lg.learner_id = e.learner_id and lg.is_billing_contact
    join public.packages p on p.code = e.package_code
    where e.status = 'active'
      and e.start_date is not null
      and p.billing_period = 'monthly'
    order by lg.guardian_id, e.id
  loop
    -- Every month from the month the learner started to the target month.
    for v_month in
      select generate_series(date_trunc('month', v_enrol.start_date), v_target, interval '1 month')::date
    loop
      -- Already billed? The unique index guarantees it, but skipping keeps
      -- the run quiet rather than relying on a swallowed conflict.
      if exists (
        select 1 from public.invoice_lines
        where enrolment_id = v_enrol.id and period_month = v_month and line_type = 'package'
      ) then
        continue;
      end if;

      if v_month = date_trunc('month', v_enrol.start_date)::date
         and v_enrol.first_month_amount_cents is not null then
        v_amount := v_enrol.first_month_amount_cents;
      else
        v_amount := public.package_price_on(v_enrol.package_code, v_month);
      end if;

      -- A zero first month (a late-month joiner the admin waived) is recorded
      -- as billed so the catch-up never runs again, but no line is raised.
      if coalesce(v_amount, 0) = 0 then
        v_amount := 0;
      end if;

      select id into v_account from public.billing_accounts where guardian_id = v_enrol.guardian_id;
      if v_account is null then
        insert into public.billing_accounts (guardian_id) values (v_enrol.guardian_id)
        returning id into v_account;
      end if;

      -- One invoice per account per run. Looked up rather than tracked in a
      -- temp table, so re-running appends to the same invoice instead of
      -- raising a duplicate - and the function is safe to call twice in one
      -- transaction, which a temp table is not.
      select i.id into v_invoice
      from public.invoices i
      where i.billing_account_id = v_account
        and i.issued_on = v_issued
        and i.status = 'issued'
      order by i.created_at
      limit 1;

      if v_invoice is null then
        insert into public.invoices
          (billing_account_id, invoice_number, period_start, period_end, issued_on, due_on, status)
        values (v_account, private.next_invoice_number(v_issued), v_target,
                (v_target + interval '1 month - 1 day')::date, v_issued, v_due, 'issued')
        returning id into v_invoice;
      end if;

      v_touched := array_append(v_touched, v_invoice);

      insert into public.invoice_lines
        (invoice_id, line_type, description, enrolment_id, package_code, learner_id,
         period_month, unit_amount_cents)
      values (v_invoice, 'package',
              to_char(v_month, 'FMMonth YYYY') || ' tuition',
              v_enrol.id, v_enrol.package_code, v_enrol.learner_id, v_month, v_amount);
    end loop;
  end loop;

  return query
    select i.id, i.billing_account_id, coalesce(sum(l.line_total_cents), 0)::bigint
    from public.invoices i
    left join public.invoice_lines l on l.invoice_id = i.id
    where i.id = any(v_touched)
    group by i.id, i.billing_account_id;
end;
$fn$;

revoke execute on function public.run_monthly_invoices(date) from public, anon;
grant execute on function public.run_monthly_invoices(date) to authenticated;

-- Late fees ----------------------------------------------------------------
-- Charged on the NEXT invoice the account receives, not retrospectively onto
-- the overdue one, so an invoice total never changes after it was sent.
create or replace function public.apply_late_fees(p_on date default current_date)
returns integer
language plpgsql security definer set search_path = ''
as $fn$
declare
  v_count integer := 0;
  v_row   record;
  v_invoice uuid;
  v_settings public.billing_settings;
begin
  if not (select private.is_admin()) then
    raise exception 'Administrators only' using errcode = 'P0001';
  end if;

  select * into v_settings from public.billing_settings
   where effective_from <= p_on and (effective_to is null or p_on < effective_to);
  if v_settings is null then return 0; end if;

  for v_row in
    select v.id, v.billing_account_id, v.invoice_number
    from public.v_invoice_status v
    where v.status = 'issued'
      and v.balance_cents > 0
      and p_on > v.due_on + v_settings.grace_days
      and not exists (
        select 1 from public.invoice_lines l
        where l.late_fee_for_invoice_id = v.id and l.line_type = 'late_fee')
  loop
    -- Attach to the newest unpaid invoice for the account, or raise one.
    select v.id into v_invoice
    from public.v_invoice_status v
    where v.billing_account_id = v_row.billing_account_id
      and v.status = 'issued' and v.issued_on >= p_on
    order by v.issued_on desc limit 1;

    if v_invoice is null then
      insert into public.invoices
        (billing_account_id, invoice_number, issued_on, due_on, status, notes)
      values (v_row.billing_account_id, private.next_invoice_number(p_on), p_on,
              p_on + v_settings.grace_days, 'issued', 'Late payment fee')
      returning id into v_invoice;
    end if;

    insert into public.invoice_lines
      (invoice_id, line_type, description, late_fee_for_invoice_id, unit_amount_cents)
    values (v_invoice, 'late_fee', 'Late payment fee — ' || v_row.invoice_number,
            v_row.id, v_settings.late_fee_cents);

    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$fn$;

revoke execute on function public.apply_late_fees(date) from public, anon;
grant execute on function public.apply_late_fees(date) to authenticated;

-- Recording a payment ------------------------------------------------------
-- Allocates oldest invoice first, which is what a parent expects and what
-- keeps the arrears figure meaningful.
create or replace function public.record_payment(
  p_billing_account_id uuid,
  p_amount_cents       integer,
  p_method             text,
  p_reference          text default '',
  p_paid_on            date default current_date
)
returns uuid
language plpgsql security definer set search_path = ''
as $fn$
declare
  v_payment   uuid;
  v_remaining integer := p_amount_cents;
  v_row       record;
  v_apply     integer;
begin
  if not (select private.is_admin()) then
    raise exception 'Administrators only' using errcode = 'P0001';
  end if;
  if p_amount_cents <= 0 then
    raise exception 'A payment must be more than zero' using errcode = 'check_violation';
  end if;

  insert into public.payments (billing_account_id, paid_on, amount_cents, method, reference, recorded_by)
  values (p_billing_account_id, p_paid_on, p_amount_cents, p_method, coalesce(p_reference, ''),
          (select auth.uid()))
  returning id into v_payment;

  for v_row in
    select v.id, v.balance_cents
    from public.v_invoice_status v
    where v.billing_account_id = p_billing_account_id
      and v.status = 'issued'
      and v.balance_cents > 0
    order by v.due_on, v.issued_on
  loop
    exit when v_remaining <= 0;
    v_apply := least(v_remaining, v_row.balance_cents);
    insert into public.payment_allocations (payment_id, invoice_id, amount_cents)
    values (v_payment, v_row.id, v_apply);
    v_remaining := v_remaining - v_apply;
  end loop;

  -- Anything left over stays unallocated and shows as a credit on the
  -- statement; it is allocated automatically by the next run.
  return v_payment;
end;
$fn$;

revoke execute on function public.record_payment(uuid, integer, text, text, date) from public, anon;
grant execute on function public.record_payment(uuid, integer, text, text, date) to authenticated;

insert into public.schema_migrations (version) values ('20261020000020_billing_run');

-- ==========================================================================
-- 20261020000021_messaging
-- ==========================================================================

-- Starting a conversation.
--
-- A thread needs its participants to exist before anyone can post, and the
-- RLS policy on messages requires the sender to already be a participant.
-- Creating the thread, adding both sides and posting the first message is
-- therefore one operation, not three.

create or replace function public.start_thread(
  p_subject       text,
  p_body          text,
  p_participants  uuid[],
  p_learner_id    uuid default null
)
returns uuid
language plpgsql security definer set search_path = ''
as $fn$
declare
  v_me     uuid := (select auth.uid());
  v_thread uuid;
  v_person uuid;
begin
  if v_me is null then
    raise exception 'Not signed in' using errcode = 'P0001';
  end if;
  if coalesce(trim(p_body), '') = '' then
    raise exception 'Write a message first' using errcode = 'check_violation';
  end if;

  -- You may only open a thread about a learner you are entitled to see.
  if p_learner_id is not null and not (select private.can_view_learner(p_learner_id)) then
    raise exception 'You cannot start a conversation about that learner' using errcode = 'P0001';
  end if;

  insert into public.message_threads (subject, learner_id, created_by)
  values (coalesce(nullif(trim(p_subject), ''), 'Message'), p_learner_id, v_me)
  returning id into v_thread;

  insert into public.thread_participants (thread_id, profile_id) values (v_thread, v_me);
  foreach v_person in array coalesce(p_participants, '{}') loop
    if v_person <> v_me then
      insert into public.thread_participants (thread_id, profile_id) values (v_thread, v_person)
      on conflict do nothing;
    end if;
  end loop;

  insert into public.messages (thread_id, sender_id, body) values (v_thread, v_me, trim(p_body));

  return v_thread;
end;
$fn$;

revoke execute on function public.start_thread(text, text, uuid[], uuid) from public, anon;
grant execute on function public.start_thread(text, text, uuid[], uuid) to authenticated;

-- Mark everything in a thread as read by the caller.
create or replace function public.mark_thread_read(p_thread_id uuid)
returns integer
language plpgsql security definer set search_path = ''
as $fn$
declare v_me uuid := (select auth.uid()); v_count integer;
begin
  if not (select private.in_thread(p_thread_id)) then
    raise exception 'Not a participant in that conversation' using errcode = 'P0001';
  end if;

  with marked as (
    insert into public.message_reads (message_id, profile_id)
    select m.id, v_me from public.messages m
    where m.thread_id = p_thread_id and m.sender_id <> v_me
    on conflict (message_id, profile_id) do nothing
    returning 1
  )
  select count(*) into v_count from marked;

  return v_count;
end;
$fn$;

revoke execute on function public.mark_thread_read(uuid) from public, anon;
grant execute on function public.mark_thread_read(uuid) to authenticated;

-- Threads the caller is in, with the last message and their unread count.
create or replace view public.v_my_threads with (security_invoker = true) as
select t.id,
       t.subject,
       t.learner_id,
       l.full_name                                   as learner_name,
       t.created_at,
       (select max(m.created_at) from public.messages m where m.thread_id = t.id) as last_message_at,
       (select m.body from public.messages m where m.thread_id = t.id
         order by m.created_at desc limit 1)          as last_message,
       (select count(*) from public.messages m
         where m.thread_id = t.id
           and m.sender_id <> (select auth.uid())
           and not exists (select 1 from public.message_reads r
                           where r.message_id = m.id and r.profile_id = (select auth.uid())))
                                                      as unread_count
from public.message_threads t
left join public.learners l on l.id = t.learner_id;

comment on view public.v_my_threads is
  'Conversation list. Unread is counted per participant, which a single '
  'read_at column on messages could not express.';

grant select on public.v_my_threads to authenticated;

insert into public.schema_migrations (version) values ('20261020000021_messaging');

-- ==========================================================================
-- 20261020000022_storage
-- ==========================================================================

-- Private storage for tutor vetting documents.
--
-- tutor_documents.storage_path has always implied a bucket; this creates it.
-- Identity documents, qualification certificates and police clearances are
-- among the most sensitive things the centre holds, so the bucket is private
-- and only administrators may read or write it (POPIA policy, Annex B5).

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'tutor-documents', 'tutor-documents', false, 52428800,
  array['image/jpeg', 'image/png', 'application/pdf']
)
on conflict (id) do update set
  public = false,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

-- Administrators only, in both directions. There is no public tutor
-- application, so nobody else ever needs to put a file here.
drop policy if exists "tutor docs: admin read" on storage.objects;
drop policy if exists "tutor docs: admin write" on storage.objects;

create policy "tutor docs: admin read" on storage.objects for select to authenticated
  using (bucket_id = 'tutor-documents' and (select private.is_admin()));

create policy "tutor docs: admin write" on storage.objects for all to authenticated
  using (bucket_id = 'tutor-documents' and (select private.is_admin()))
  with check (bucket_id = 'tutor-documents' and (select private.is_admin()));

insert into public.schema_migrations (version) values ('20261020000022_storage');

-- ==========================================================================
-- 20261020000023_backfill_existing_users
-- ==========================================================================

-- Give existing auth accounts a profile under the new schema.
--
-- `handle_new_user` only fires on INSERT into auth.users, so anyone who signed
-- up before this schema existed has an account they can still log in with and
-- no profile to log in to. getSession() returns null without a profile, so the
-- app would treat them as signed out for ever.
--
-- Dropping and rebuilding `public` does not touch `auth`, so those accounts
-- survive a redeploy; this is what reconnects them.
--
-- A no-op on a fresh database, where auth.users is empty.

insert into public.profiles (id, full_name, phone, created_at)
select u.id,
       coalesce(nullif(trim(u.raw_user_meta_data ->> 'full_name'), ''), split_part(u.email, '@', 1)),
       u.raw_user_meta_data ->> 'phone',
       u.created_at
from auth.users u
where not exists (select 1 from public.profiles p where p.id = u.id)
on conflict (id) do nothing;

-- Everyone who self-registered is a parent or guardian. Roles that the centre
-- grants - tutor, admin - are assigned deliberately, never inferred from the
-- old schema's self-selected sign-up role.
insert into public.user_roles (user_id, role)
select p.id, 'parent'
from public.profiles p
where not exists (select 1 from public.user_roles r where r.user_id = p.id)
on conflict do nothing;

insert into public.guardians (profile_id)
select p.id
from public.profiles p
join public.user_roles r on r.user_id = p.id and r.role = 'parent'
where not exists (select 1 from public.guardians g where g.profile_id = p.id)
on conflict do nothing;

insert into public.schema_migrations (version) values ('20261020000023_backfill_existing_users');

commit;

-- Expect: migrations_recorded = 23, tables = 75, profiles_backfilled = 6 or 7
select (select count(*) from public.schema_migrations)              as migrations_recorded,
       (select count(*) from pg_tables where schemaname = 'public') as tables,
       (select count(*) from public.profiles)                       as profiles_backfilled;
